    type            heatTransferLimitedPhaseChange;
    libs            ("libmultiphaseEulerFvModels.so");

    phases          (steam water);

    energySemiImplicit yes;
    pressureImplicit no;

    saturationTemperature
    {
        type            constant;
        value           372.76;
    }
}

phaseSurfaceBoiling.usage:
Example usage:

phaseSurfaceBoiling
{
    type            phaseSurfaceBoiling;
    libs            ("libmultiphaseEulerFvModels.so");

    phase           solid;

    // Note: Order is important. This model is one-way. It turns liquid
    // into vapour. The phases should be specified in this order.
    phases          (water steam);

    energySemiImplicit no;

    saturationTemperature
    {
        type            constant;
        value           372.76;
    }

    partitioningModel
    {
        type            Lavieville;
        alphaCrit       0.2;
    }

    nucleationSiteModel
    {
        type            LemmertChawla;
    }

    departureDiameterModel
    {
        type            TolubinskiKostanchuk;
    }

    departureFrequencyModel
    {
        type            KocamustafaogullariIshii;
        Cf              1.18;
    }
}

wallBoiling.usage:
Example usage:

wallBoiling
{
    type            wallBoiling;
    libs            ("libmultiphaseEulerFvModels.so");

    // Note: Order is important. This model is one-way. It turns liquid
    // into vapour. The phases should be specified in this order.
    phases          (water steam);

    energySemiImplicit no;

    saturationTemperature
    {
        type            constant;
        value           372.76;
    }

    partitioningModel
    {
        type            Lavieville;
        alphaCrit       0.2;
    }

    nucleationSiteModel
    {
        type            LemmertChawla;
        Cn              1;
        NRef            30000000;
        deltaTRef       10;
    }

    departureDiameterModel
    {
        type            TolubinskiKostanchuk;
        dRef            0.00024;
        dMax            0.0014;
        dMin            1e-06;
    }

    departureFrequencyModel
    {
        type            KocamustafaogullariIshii;
        Cf              1.18;
    }
}

In addition to the above fvModel specification, wall patches on which
boiling is to be calculated should have an alphatBoilingWallFunction
boundary condition applied to the turbulent thermal diffusivity field.

